import { chromium, expect } from '@playwright/test';
import assert from 'node:assert/strict';
import { randomBytes } from 'node:crypto';
import { execFileSync } from 'node:child_process';
const [sha,tag,probePath]=process.argv.slice(2);
const rat='https://dev-rum-ra.daisycloversoftware.uk', dev='https://dev-rum.daisycloversoftware.uk';
assert.match(sha,/^[a-f0-9]{40}$/); assert.match(tag,/^qa181[a-z0-9]{8}$/);
const db=op=>JSON.parse(execFileSync('bash',[probePath,sha,op,tag],{encoding:'utf8',timeout:60000}));
const names={source:`Test Observatory ${tag}`,existing:`Test Atlas ${tag}`,normal:`Violet Lantern ${tag}`,retry:`Bronze Sundial ${tag}`};
const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
const page=await browser.newPage({viewport:{width:1440,height:940},serviceWorkers:'block'});page.setDefaultTimeout(30000);
let source,existing,actor,mode='register',pairTarget=null,allowedRating=null,allowedRetry=null,restoreNeeded=false;
const targets=new Set(),ratingsPosted=new Set();
const idOk=id=>typeof id==='string'&&/^[0-9a-z]{26}$/.test(id);
const api='/api/v1/rate-anything/',route=id=>`${rat}/e/thing~${id}`;
await page.route('**/*',async r=>{const q=r.request(),u=new URL(q.url());if([rat,dev].includes(u.origin)&&['GET','HEAD','OPTIONS'].includes(q.method()))return r.continue();if(u.origin!==rat||q.method()!=='POST')return r.abort();const path=u.pathname;let ok=false;
 if(mode==='register'&&path===api+'auth/register'){ok=q.postDataJSON()?.username===tag;}
 if(mode==='create'&&path===api+'standalone-things'){const v=q.postDataJSON();ok=[names.source,names.normal,names.retry].includes(v.name)&&(v.name===names.source?!v.connection:v.connection?.sourceId===source&&v.connection?.type==='related_to'&&v.connection?.direction==='outgoing');}
 if(mode==='rate'&&path===api+'rating'){const v=q.postDataJSON();ok=targets.has(v.entityId)&&v.entityId===allowedRating&&!ratingsPosted.has(v.entityId);if(ok)ratingsPosted.add(v.entityId);}
 if(mode==='existing'&&path===api+`things/${source}/connections`){const v=q.postDataJSON();ok=v.targetEntityId===pairTarget&&pairTarget===existing&&v.relationshipType==='related_to';}
 if(mode==='retry'&&allowedRetry&&path===api+`standalone-things/${allowedRetry}/retry-connection`){ok=true;}
 if(!ok){console.log('BLOCKED_UNEXPECTED_WRITE',path);return r.abort();}return r.continue();});
const waitPost=path=>page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname===api+path,{timeout:35000});
async function chooser(name){await page.goto(route(source));await expect(page.locator('.rat-workspace-id')).toHaveText(source);await page.getByRole('button',{name:'Add a connection',exact:true}).click();await page.getByLabel('Search Things to connect').fill(name);await page.getByRole('button',{name:'Search existing Things'}).click();await expect(page.getByRole('button',{name:/None of these — add a missing Thing/})).toBeVisible();}
async function pending(name,label,independent=false){mode='create';if(independent){await page.goto(`${rat}/search?q=${encodeURIComponent(names.source)}&active=${source}`);await page.getByRole('button',{name:'Add another Thing with this name'}).click();}else{await chooser(name);await page.getByRole('button',{name:/None of these — add a missing Thing/}).click();}
const form=page.getByRole('dialog');await expect(form.getByLabel('Thing name')).toHaveValue(name);await form.getByRole('combobox').fill(label);await form.getByRole('option').getByRole('button',{name:new RegExp('^'+label+'(?:\\s|General Thing|Existing type)')}).first().click();await form.getByLabel('Thing description').fill('Disposable RAT181 browser acceptance: '+name);let w=waitPost('standalone-things');await form.getByRole('button',{name:'Check and add',exact:true}).click();let r=await w;if(r.status()===409){const j=await r.json();assert.equal(j.code,'entity_candidates_require_confirmation');w=waitPost('standalone-things');await form.getByRole('button',{name:/No — this is a different thing/}).click();r=await w;}assert.equal(r.status(),201,'fixture create '+r.status());const v=await r.json(),id=v.data.id,j=v.meta.journey.id;assert.ok(idOk(id)&&idOk(j)&&id!==source&&id!==existing);targets.add(id);assert.equal(v.data.publicationState,'pending');if(independent){assert.equal(v.meta.connection,null);}else{assert.deepEqual(v.meta.connection,{sourceId:source,targetId:id,actorId:actor,type:'related_to',direction:'outgoing',state:'pending'});}
await expect(page).toHaveURL(new RegExp('/rate/'+id));await page.reload();const snapshot=db('inspect');assert.ok(!snapshot.edges.some(e=>[e.source,e.target].includes(id)));const saved=snapshot.journeys.find(x=>x.id===j&&x.target===id);assert.deepEqual(saved.intent,v.meta.connection);console.log('PENDING_PERSISTED',JSON.stringify({id,j,intent:saved.intent}));return {id,j};}
async function rate(t){mode='rate';allowedRating=t.id;const f=page.locator('.rat-rating-flow');await expect(f).toBeVisible();await expect(f.locator('.rating-card__status').filter({hasText:'Checking your rating account'})).toHaveCount(0,{timeout:45000});const thumb=f.getByRole('radio',{name:/^3: Good/});await thumb.click();await expect(thumb).toHaveAttribute('aria-checked','true');const next=f.getByRole('button',{name:'Continue',exact:true});await next.click();await f.locator('.rat-rating-choice-grid button').first().click();await next.click();await f.getByLabel('Why this verdict?').fill('Disposable DEV acceptance rating for this test fixture only.');await next.click();const w=waitPost('rating');await f.getByRole('button',{name:'Submit rating',exact:true}).click();const r=await w;assert.ok([200,201].includes(r.status()),'initial rating: '+r.status());await expect(f).toHaveAttribute('data-rating-state','complete');mode='read';allowedRating=null;}
async function existingLink(){await chooser(names.existing);await page.getByRole('button',{name:new RegExp('^'+names.existing+' ·')}).click();mode='existing';pairTarget=existing;const w=waitPost(`things/${source}/connections`);await page.getByRole('button',{name:'Confirm connection',exact:true}).click();const r=await w;assert.ok([200,201].includes(r.status()));mode='read';return r.json();}
function edge(s,id,count=1){const a=s.edges.filter(x=>[x.source,x.target].includes(id)&&[x.source,x.target].includes(source));assert.equal(a.length,count);if(count){assert.equal(a[0].verification,'unverified');assert.equal(a[0].visibility,'public');assert.equal(a[0].provenance,'user_submitted');assert.equal(a[0].actor,actor);return a[0].id;}}
try{await page.goto(rat);await page.getByRole('button',{name:'Sign in',exact:true}).click();const login=page.getByRole('dialog');await login.getByRole('button',{name:'Create account',exact:true}).click();const pw=randomBytes(24).toString('hex')+'Aa7!';await login.getByLabel('Username',{exact:true}).fill(tag);await login.getByLabel('Email',{exact:true}).fill(`${tag}@example.test`);await login.getByLabel('Password',{exact:true}).fill(pw);await login.getByLabel('Confirm password',{exact:true}).fill(pw);for(const c of await login.getByRole('checkbox').all())await c.check();const reg=waitPost('auth/register');await login.getByRole('button',{name:'Create RAT account and continue'}).click();assert.equal((await reg).status(),201);mode='read';({source,existing,actor}=db('seed'));assert.ok([source,existing,actor].every(idOk));console.log('FIXTURE_SCOPE',JSON.stringify({tag,source,existing,actor}));
 const a=await pending(names.normal,'Product');await rate(a);await expect(page.getByText('Connection saved.',{exact:true})).toBeVisible();let snap=db('inspect');const first=edge(snap,a.id);assert.equal(snap.journeys.find(j=>j.id===a.j).intent.relationshipId,first);await page.getByRole('button',{name:'Return to connected Things'}).click();const panel=page.locator('#connections');await expect(panel.locator('header span')).toHaveText('1 public');await panel.getByRole('button',{name:new RegExp(names.normal)}).click();await expect(page.locator('.rat-workspace-id')).toHaveText(a.id);await page.reload();await panel.getByRole('button',{name:new RegExp(names.source)}).click();await expect(page.locator('.rat-workspace-id')).toHaveText(source);await page.reload();await expect(panel.locator('header span')).toHaveText('1 public');console.log('AUTOMATIC_PUBLICATION_RECIPROCAL_REFRESH_PASS',first);
 const e1=await existingLink(),e2=await existingLink();assert.equal(e1.meta.created,true);assert.equal(e2.meta.created,false);assert.equal(e1.data.id,e2.data.id);snap=db('inspect');assert.equal(edge(snap,existing),e1.data.id);assert.deepEqual(snap.entities.find(x=>x.id===existing).ratingIds,[]);console.log('EXISTING_REPEAT_PASS',e1.data.id);
 const b=await pending(names.source,'YouTube Channel',true);await rate(b);snap=db('inspect');assert.equal(snap.entities.find(x=>x.id===b.id).state,'published');assert.equal(snap.entities.find(x=>x.id===b.id).rum,false);assert.ok(!snap.edges.some(e=>[e.source,e.target].includes(b.id)));console.log('INDEPENDENT_NO_EDGE_RUM_EXCLUDED_PASS',b.id);
 const c=await pending(names.retry,'Product');restoreNeeded=true;db('hide');await rate(c);await expect(page.getByText('The Thing was published but the connection was not saved.',{exact:false})).toBeVisible();let failed=db('inspect');edge(failed,c.id,0);const original=failed.entities.find(x=>x.id===c.id);assert.equal(original.state,'published');assert.equal(original.ratingIds.length,1);assert.equal(failed.journeys.find(x=>x.id===c.j).intent.state,'retry');db('restore');restoreNeeded=false;await page.reload();mode='retry';allowedRetry=c.j;const wr=waitPost(`standalone-things/${c.j}/retry-connection`);await page.getByRole('button',{name:'Retry connection only'}).click();assert.equal((await wr).status(),200);await expect(page.getByText('Connection saved.',{exact:true})).toBeVisible();snap=db('inspect');const last=edge(snap,c.id);assert.deepEqual(snap.entities.find(x=>x.id===c.id).ratingIds,original.ratingIds);assert.equal(snap.entities.length,5);assert.equal(snap.edges.length,3);assert.equal(snap.journeys.length,3);assert.deepEqual(snap.entities.find(x=>x.id===source).ratingIds,[]);assert.deepEqual(snap.entities.find(x=>x.id===existing).ratingIds,[]);await page.getByRole('button',{name:'Return to connected Things'}).click();await page.reload();await expect(panel.locator('header span')).toHaveText('3 public');console.log('FULL_ACCEPTANCE_PASS',JSON.stringify({sha,chromium:browser.version(),tag,source,existing,newTarget:a.id,newEdge:first,existingEdge:e1.data.id,independent:b.id,retryTarget:c.id,retryEdge:last,fixtureRatings:ratingsPosted.size}));
} catch(e){console.log('FAILURE_STAGE',mode,new URL(page.url()).pathname);console.log('VISIBLE_ERRORS',await page.locator('.form-error,[role=alert]').allTextContents());throw e;}finally{try{if(restoreNeeded)db('restore');}finally{await browser.close();}}
